// Command gen-contracts 从 api/events.yaml 与 api/openapi.yaml 生成 Go 与 TS 类型。
//
// 为什么自写生成器而非 oapi-codegen（Day 05 有意偏离，同 sqlc→手写的理由）：
//   - 契约 Schema 刻意扁平（§23 M0），一个小生成器即可覆盖，不引入 oapi-codegen 的
//     OpenAPI 3.1 支持不全与大依赖树；
//   - 生成逻辑完全在控制内，输出稳定、可审。
//
// 产物（均带 "DO NOT EDIT" 头，纳入版本库）：
//
//	internal/events/events_gen.go   事件类型常量 + payload 结构体
//	web/src/events.gen.ts           事件类型联合 + payload 接口
//	api/gen/openapi_gen.go          组件 Schema 结构体 + 路由/operationId 常量
//
// 用法：go run ./cmd/gen-contracts   （也被 //go:generate 调用）
package main

import (
	"fmt"
	"go/format"
	"os"
	"sort"
	"strings"

	"go.yaml.in/yaml/v3"
)

func main() {
	if err := run(); err != nil {
		fmt.Fprintln(os.Stderr, "gen-contracts:", err)
		os.Exit(1)
	}
	fmt.Println("gen-contracts: ok")
}

func run() error {
	if err := genEvents("api/events.yaml"); err != nil {
		return fmt.Errorf("events: %w", err)
	}
	if err := genOpenAPI("api/openapi.yaml"); err != nil {
		return fmt.Errorf("openapi: %w", err)
	}
	return nil
}

// ---------- events.yaml ----------

type eventsDoc struct {
	Version int                 `yaml:"version"`
	Events  map[string]eventDef `yaml:"events"`
}

type eventDef struct {
	Description string            `yaml:"description"`
	Payload     map[string]string `yaml:"payload"`
}

func genEvents(path string) error {
	raw, err := os.ReadFile(path)
	if err != nil {
		return err
	}
	var doc eventsDoc
	if err := yaml.Unmarshal(raw, &doc); err != nil {
		return err
	}
	names := sortedKeys(doc.Events)

	// --- Go ---
	var b strings.Builder
	b.WriteString("// Code generated by cmd/gen-contracts from api/events.yaml. DO NOT EDIT.\n\n")
	b.WriteString("package events\n\n")
	b.WriteString("// EventType 是 SSE 事件类型（§15.6 唯一来源：api/events.yaml）。\n")
	b.WriteString("type EventType string\n\n")
	b.WriteString("const (\n")
	for _, n := range names {
		fmt.Fprintf(&b, "\t%s EventType = %q\n", pascal(n), n)
	}
	b.WriteString(")\n\n")
	b.WriteString("// All 是全部事件类型（契约测试据此核对 §15.6 完整性）。\n")
	b.WriteString("var All = []EventType{\n")
	for _, n := range names {
		fmt.Fprintf(&b, "\t%s,\n", pascal(n))
	}
	b.WriteString("}\n\n")
	for _, n := range names {
		ev := doc.Events[n]
		fmt.Fprintf(&b, "// %sPayload —— %s\n", pascal(n), ev.Description)
		fmt.Fprintf(&b, "type %sPayload struct {\n", pascal(n))
		for _, f := range sortedKeys(ev.Payload) {
			gt, err := goScalar(ev.Payload[f])
			if err != nil {
				return fmt.Errorf("事件 %s 字段 %s: %w", n, f, err)
			}
			fmt.Fprintf(&b, "\t%s %s `json:%q`\n", pascal(f), gt, f)
		}
		b.WriteString("}\n\n")
	}
	if err := writeGoFile("internal/events/events_gen.go", b.String()); err != nil {
		return err
	}

	// --- TS ---
	var t strings.Builder
	t.WriteString("// Code generated by cmd/gen-contracts from api/events.yaml. DO NOT EDIT.\n\n")
	t.WriteString("export type EventType =\n")
	for i, n := range names {
		sep := "|"
		if i == 0 {
			sep = " "
		}
		fmt.Fprintf(&t, "  %s %q\n", sep, n)
	}
	t.WriteString(";\n\n")
	t.WriteString("export const ALL_EVENTS: EventType[] = [\n")
	for _, n := range names {
		fmt.Fprintf(&t, "  %q,\n", n)
	}
	t.WriteString("];\n\n")
	for _, n := range names {
		ev := doc.Events[n]
		fmt.Fprintf(&t, "export interface %sPayload {\n", pascal(n))
		for _, f := range sortedKeys(ev.Payload) {
			ty, err := tsScalar(ev.Payload[f])
			if err != nil {
				return fmt.Errorf("事件 %s 字段 %s (TS): %w", n, f, err)
			}
			fmt.Fprintf(&t, "  %s: %s;\n", f, ty)
		}
		t.WriteString("}\n\n")
	}
	return writeRawFile("web/src/events.gen.ts", t.String())
}

// ---------- openapi.yaml ----------

type openapiDoc struct {
	Paths      map[string]pathItem `yaml:"paths"`
	Components struct {
		Schemas map[string]schema `yaml:"schemas"`
	} `yaml:"components"`
}

type pathItem struct {
	Get    *operation `yaml:"get"`
	Post   *operation `yaml:"post"`
	Put    *operation `yaml:"put"`
	Delete *operation `yaml:"delete"`
	Patch  *operation `yaml:"patch"`
}

func (p pathItem) methods() []struct {
	Method string
	Op     *operation
} {
	return []struct {
		Method string
		Op     *operation
	}{
		{"GET", p.Get}, {"POST", p.Post}, {"PUT", p.Put},
		{"DELETE", p.Delete}, {"PATCH", p.Patch},
	}
}

type operation struct {
	OperationID string `yaml:"operationId"`
	Summary     string `yaml:"summary"`
}

type schema struct {
	Type       string          `yaml:"type"`
	Properties map[string]prop `yaml:"properties"`
	Required   []string        `yaml:"required"`
}

type prop struct {
	Type  string `yaml:"type"`
	Ref   string `yaml:"$ref"`
	Items *prop  `yaml:"items"`
}

func genOpenAPI(path string) error {
	raw, err := os.ReadFile(path)
	if err != nil {
		return err
	}
	var doc openapiDoc
	if err := yaml.Unmarshal(raw, &doc); err != nil {
		return err
	}

	// 路由 / operationId 注册表（先收集排序）。
	type routeEntry struct{ opID, method, path string }
	var routes []routeEntry
	for _, p := range sortedKeys(doc.Paths) {
		for _, m := range doc.Paths[p].methods() {
			if m.Op != nil && m.Op.OperationID != "" {
				routes = append(routes, routeEntry{m.Op.OperationID, m.Method, p})
			}
		}
	}
	sort.Slice(routes, func(i, j int) bool { return routes[i].opID < routes[j].opID })

	var routesB strings.Builder
	routesB.WriteString("// Route 描述一个路由契约（operationId → 方法 + 路径）。\n")
	routesB.WriteString("type Route struct{ OperationID, Method, Path string }\n\n")
	routesB.WriteString("// Routes 是全部路由（契约测试据此核对每路由有 operationId）。\n")
	routesB.WriteString("var Routes = []Route{\n")
	for _, r := range routes {
		fmt.Fprintf(&routesB, "\t{OperationID: %q, Method: %q, Path: %q},\n", r.opID, r.method, r.path)
	}
	routesB.WriteString("}\n\n")

	// 组件 Schema → 结构体（同时判断是否需要 encoding/json）。
	needJSON := false
	var body strings.Builder
	for _, name := range sortedKeys(doc.Components.Schemas) {
		s := doc.Components.Schemas[name]
		req := map[string]bool{}
		for _, r := range s.Required {
			req[r] = true
		}
		fmt.Fprintf(&body, "type %s struct {\n", name)
		for _, f := range sortedKeys(s.Properties) {
			gt, err := goType(s.Properties[f])
			if err != nil {
				return fmt.Errorf("Schema %s 字段 %s: %w", name, f, err)
			}
			if strings.Contains(gt, "json.RawMessage") {
				needJSON = true
			}
			tag := f
			if !req[f] {
				tag = f + ",omitempty"
			}
			fmt.Fprintf(&body, "\t%s %s `json:%q`\n", pascal(f), gt, tag)
		}
		body.WriteString("}\n\n")
	}

	// 按正确顺序组装：注释 → package → import(如需) → 路由 → 结构体。
	var b strings.Builder
	b.WriteString("// Code generated by cmd/gen-contracts from api/openapi.yaml. DO NOT EDIT.\n\n")
	b.WriteString("package apigen\n\n")
	if needJSON {
		b.WriteString("import \"encoding/json\"\n\n")
	}
	b.WriteString(routesB.String())
	b.WriteString(body.String())

	return writeGoFile("api/gen/openapi_gen.go", b.String())
}

// ---------- 类型映射 ----------

// Q-12：未知类型一律响亮失败，不静默回退 string——契约里拼错类型(如 integre)必须报错。

func goScalar(t string) (string, error) {
	switch t {
	case "string":
		return "string", nil
	case "integer":
		return "int64", nil
	case "number":
		return "float64", nil
	case "boolean":
		return "bool", nil
	default:
		return "", fmt.Errorf("未知标量类型 %q（payload 字段类型只能是 string/integer/number/boolean）", t)
	}
}

func tsScalar(t string) (string, error) {
	switch t {
	case "string":
		return "string", nil
	case "integer", "number":
		return "number", nil
	case "boolean":
		return "boolean", nil
	default:
		return "", fmt.Errorf("未知标量类型 %q", t)
	}
}

func goType(p prop) (string, error) {
	if p.Ref != "" {
		return refName(p.Ref), nil
	}
	switch p.Type {
	case "string":
		return "string", nil
	case "integer":
		return "int64", nil
	case "number":
		return "float64", nil
	case "boolean":
		return "bool", nil
	case "object":
		return "json.RawMessage", nil
	case "array":
		if p.Items != nil {
			inner, err := goType(*p.Items)
			if err != nil {
				return "", err
			}
			return "[]" + inner, nil
		}
		return "[]any", nil
	default:
		return "", fmt.Errorf("未知 Schema 类型 %q（只支持 string/integer/number/boolean/object/array/$ref）", p.Type)
	}
}

func refName(ref string) string {
	if i := strings.LastIndex(ref, "/"); i >= 0 {
		return ref[i+1:]
	}
	return ref
}

// ---------- 工具 ----------

func sortedKeys[V any](m map[string]V) []string {
	ks := make([]string, 0, len(m))
	for k := range m {
		ks = append(ks, k)
	}
	sort.Strings(ks)
	return ks
}

var initialisms = map[string]string{
	"id": "ID", "url": "URL", "api": "API", "ip": "IP", "oast": "OAST",
	"sha256": "SHA256", "ts": "TS", "json": "JSON", "html": "HTML", "ui": "UI",
}

func pascal(s string) string {
	parts := strings.FieldsFunc(s, func(r rune) bool { return r == '.' || r == '_' || r == '-' })
	var b strings.Builder
	for _, p := range parts {
		if up, ok := initialisms[strings.ToLower(p)]; ok {
			b.WriteString(up)
			continue
		}
		if p != "" {
			b.WriteString(strings.ToUpper(p[:1]) + p[1:])
		}
	}
	return b.String()
}

func writeGoFile(path, src string) error {
	formatted, err := format.Source([]byte(src))
	if err != nil {
		// 出错时写未格式化版，便于排查。
		_ = writeRawFile(path, src)
		return fmt.Errorf("format %s: %w", path, err)
	}
	return writeRawFile(path, string(formatted))
}

func writeRawFile(path, content string) error {
	if i := strings.LastIndex(path, "/"); i >= 0 {
		if err := os.MkdirAll(path[:i], 0o755); err != nil {
			return err
		}
	}
	return os.WriteFile(path, []byte(content), 0o644)
}
